@import "tailwindcss";

@theme {
  /* Brand typeface (Geist), injected as CSS vars by next/font in app/layout.tsx.
     Mapping them here makes Tailwind's `font-sans` / `font-mono` utilities — and the
     body default below — resolve to Geist, with a graceful system fallback. */
  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, "SFMono-Regular", "Menlo", monospace;

  --color-brand-50: #f2f0ff;
  --color-brand-100: #e4e0ff;
  --color-brand-200: #c9c2ff;
  --color-brand-300: #a89aff;
  --color-brand-400: #8a70fb;
  --color-brand-500: #6f47f5;
  --color-brand-600: #5f2ee8;
  --color-brand-700: #5124c4;
  --color-brand-800: #421fa0;
  --color-brand-900: #371d7f;

  --color-navy-950: #060a14;
  --color-navy-900: #0a101f;
  --color-navy-850: #0d1526;
  --color-navy-800: #111a30;
  --color-navy-700: #1a2540;
  --color-navy-600: #253354;

  --color-accent-blue: #3b82f6;
  --color-accent-cyan: #22d3ee;

  --animate-fade-up: fade-up 0.4s ease-out both;
  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;

  /* Admin attention indicators (components/admin/AdminIndicators.tsx). `bell-shake`
     runs once whenever a new ticket / live-chat reply / email arrives; opt-in via
     `motion-safe:` at the call site so reduced-motion users just see the badge. */
  --animate-bell-shake: bell-shake 0.9s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
  @keyframes bell-shake {
    0%, 100% { transform: rotate(0); }
    10%, 50%, 90% { transform: rotate(-11deg); }
    30%, 70% { transform: rotate(11deg); }
  }

  /* Pricing explorer interactions. `price-pop` runs on every billing-cycle change
     (re-keyed number), `panel-in` on every product-tab switch. Both are opt-in via
     `motion-safe:` at the call site, so reduced-motion users see the resting frame. */
  --animate-price-pop: price-pop 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-panel-in: panel-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;

  @keyframes price-pop {
    from { opacity: 0; transform: translateY(7px); filter: blur(3px); }
    to { opacity: 1; transform: translateY(0); filter: blur(0); }
  }
  @keyframes panel-in {
    from { opacity: 0; transform: translateY(12px) scale(0.994); }
    to { opacity: 1; transform: translateY(0) scale(1); }
  }
  /* GameHero logo entrance — a soft pop as the themed hero mounts. Applied via
     the `motion-safe:animate-gh-pop` utility so reduced-motion users see no motion. */
  @keyframes gh-pop {
    from { opacity: 0; transform: translateY(10px) scale(0.9); }
    to { opacity: 1; transform: translateY(0) scale(1); }
  }
  --animate-gh-pop: gh-pop 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;

  /* Showcase mock-screen animations (marketing product pages). All are opt-in
     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
     resting state (bars full, lines visible) with no motion. */
  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-eq: eq 1.7s ease-in-out infinite;
  --animate-blink: blink 1.1s steps(1) infinite;
  --animate-sweep: sweep 3.4s ease-in-out infinite;
  --animate-line-in: line-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;

  @keyframes fade-up {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
  }
  @keyframes pulse-dot {
    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
  }
  /* One-shot bar grow (origin at the base). Resting state = full. */
  @keyframes grow-up {
    from { transform: scaleY(0.06); }
    to { transform: scaleY(1); }
  }
  /* One-shot progress/usage fill. Resting state = full width. */
  @keyframes grow-x {
    from { transform: scaleX(0); }
    to { transform: scaleX(1); }
  }
  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
  @keyframes eq {
    0%, 100% { transform: scaleY(0.35); }
    50% { transform: scaleY(1); }
  }
  /* Terminal cursor blink. Resting state = visible. */
  @keyframes blink {
    0%, 49% { opacity: 1; }
    50%, 100% { opacity: 0; }
  }
  /* Soft light sweep across a chart/highlight. */
  @keyframes sweep {
    0% { transform: translateX(-120%); opacity: 0; }
    40%, 60% { opacity: 0.7; }
    100% { transform: translateX(320%); opacity: 0; }
  }
  /* Staggered line/row reveal. Resting state = visible. */
  @keyframes line-in {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
  }
}

body {
  @apply bg-navy-950 text-slate-100 antialiased font-sans;
  background-image:
    radial-gradient(ellipse 80% 50% at 20% -10%, rgb(111 71 245 / 0.13), transparent),
    radial-gradient(ellipse 60% 40% at 90% 0%, rgb(59 130 246 / 0.10), transparent);
  background-attachment: fixed;
}

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #253354; border-radius: 8px; border: 2px solid #060a14; }
::-webkit-scrollbar-thumb:hover { background: #34456e; }

@layer components {
  /* Surfaces */
  .card {
    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
  }
  .card-hover {
    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
  }
  .glass {
    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
  }
  .glow-brand {
    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
  }
  /* Subtle outer glow for the deploy wizard's outer container — same violet→cyan
     brand pair as .hero-aura / DeployHub's tile glows, just restrained: a checkout
     flow, not a marketing hero. Self-contained (restates .card's own shadow layers
     plus two soft ambient glow layers) so it doesn't depend on CSS source order
     when applied alongside .card. */
  .wizard-shell {
    box-shadow:
      0 1px 0 0 rgb(255 255 255 / 0.03) inset,
      0 8px 32px -12px rgb(0 0 0 / 0.5),
      0 0 60px -22px rgb(111 71 245 / 0.35),
      0 0 90px -36px rgb(34 211 238 / 0.22);
  }

  /* Typography */
  .grad-text {
    @apply bg-gradient-to-r from-accent-blue via-brand-400 to-brand-500 bg-clip-text text-transparent;
  }
  .page-title {
    @apply text-2xl font-bold tracking-tight;
  }
  .section-label {
    @apply text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500;
  }

  /* Buttons */
  .btn-primary,
  .btn-secondary,
  .btn-danger,
  .btn-ghost,
  .btn-deploy {
    @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50;
  }
  .btn-primary {
    @apply bg-gradient-to-r from-accent-blue to-brand-500 text-white hover:brightness-110;
    box-shadow: 0 4px 20px -6px rgb(111 71 245 / 0.5);
  }
  /* The sleek, unified "Deploy" CTA used across every service page. Animated
     gradient-shift + a one-shot shimmer sweep on hover + an arrow nudge. */
  @keyframes btn-deploy-sweep {
    0% { transform: translateX(-130%) skewX(-12deg); }
    100% { transform: translateX(130%) skewX(-12deg); }
  }
  .btn-deploy {
    @apply relative overflow-hidden rounded-full px-5 text-white;
    background-image: linear-gradient(110deg, var(--color-brand-500), var(--color-accent-blue), var(--color-accent-cyan), var(--color-brand-500));
    background-size: 220% 100%;
    background-position: 0% 0;
    box-shadow: 0 8px 26px -8px rgb(111 71 245 / 0.55), inset 0 1px 0 0 rgb(255 255 255 / 0.18);
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-position 0.6s ease;
  }
  .btn-deploy:hover {
    transform: translateY(-1px);
    background-position: 100% 0;
    box-shadow: 0 12px 34px -8px rgb(111 71 245 / 0.7), inset 0 1px 0 0 rgb(255 255 255 / 0.25);
  }
  .btn-deploy::before {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    width: 60%;
    background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.38), transparent);
    transform: translateX(-130%) skewX(-12deg);
    pointer-events: none;
  }
  .btn-deploy:hover::before {
    animation: btn-deploy-sweep 0.75s ease;
  }
  .btn-deploy .dep-arrow {
    transition: transform 0.25s ease;
  }
  .btn-deploy:hover .dep-arrow {
    transform: translateX(3px);
  }
  @media (prefers-reduced-motion: reduce) {
    .btn-deploy,
    .btn-deploy:hover {
      transition: none;
    }
    .btn-deploy:hover::before {
      animation: none;
    }
    .btn-deploy:hover .dep-arrow {
      transform: none;
    }
  }
  .btn-secondary {
    @apply border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20 hover:bg-white/[0.08];
  }
  .btn-danger {
    @apply border border-red-500/30 bg-red-500/10 text-red-300 hover:bg-red-500/20;
  }
  .btn-ghost {
    @apply text-slate-400 hover:bg-white/[0.05] hover:text-white;
  }

  /* Forms */
  .input {
    @apply w-full rounded-xl border border-white/10 bg-navy-900/80 px-3.5 py-2.5 text-sm text-slate-100 outline-none transition-colors placeholder:text-slate-500 focus:border-brand-400/60 focus:ring-2 focus:ring-brand-500/20;
  }
  .label {
    @apply mb-1.5 block text-xs font-medium uppercase tracking-wide text-slate-400;
  }

  /* Nav */
  .nav-item {
    @apply flex items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white;
  }
  .nav-item-active {
    @apply bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white;
    box-shadow: 0 4px 16px -6px rgb(111 71 245 / 0.6);
  }

  /* Tables */
  .table-shell {
    @apply w-full text-sm;
  }
  .table-shell thead th {
    @apply px-4 py-3 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500;
  }
  .table-shell tbody tr {
    @apply border-t border-white/[0.05] transition-colors hover:bg-white/[0.02];
  }
  .table-shell tbody td {
    @apply px-4 py-3;
  }

  /* Misc */
  .kbd {
    @apply rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[11px] text-slate-400;
  }
  .divider {
    @apply my-4 border-t border-white/[0.06];
  }
  .skeleton {
    @apply animate-pulse rounded-lg bg-white/[0.06];
  }

  /* ── Marketing design system (v2 redesign) ─────────────────────────────────
     Shared primitives so every page reads as one designed site. The Section
     component alternates these background "tones" to give the long pages rhythm
     instead of a flat stack. Colors/animations are the existing brand system. */

  /* Eyebrow label above section/hero headings (the ubiquitous uppercase tag). */
  .eyebrow {
    @apply inline-flex items-center gap-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-brand-300;
  }
  .eyebrow-pill {
    @apply inline-flex items-center gap-2 rounded-full border border-brand-500/20 bg-brand-500/[0.08] px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-brand-200;
  }

  /* Section background tones for alternating rhythm. "panel" is a hair lighter
     than the page with hairline separators; "deep" recedes. Replaces one-off
     inline gradients scattered across pages. */
  .tone-panel {

  .tone-panel {
    @apply border-y border-white/[0.05] bg-navy-900/40;
  }
  .tone-deep {
    background: linear-gradient(180deg, rgb(6 10 20 / 0) 0%, rgb(8 12 24 / 0.6) 50%, rgb(6 10 20 / 0) 100%);
  }

  /* Foreground tokens so tone-aware primitives (SectionTitle, FeatureCard) flip
     text automatically. Default = the dark theme's light text. */
  :root {
    --fg: #ffffff;
    --fg-muted: #94a3b8; /* slate-400 */
  }

  /* "light" tone — a rare, deliberate light band to break up the dark theme and
     divide long pages (used sparingly, ~one per page). Flips the foreground
     tokens to dark and restyles surfaces/buttons inside so everything stays
     legible without touching each call site. */
  .tone-light {
    @apply border-y border-slate-200/70 text-slate-700;
    background: linear-gradient(180deg, #f4f3fb 0%, #ebe9f5 100%);
    --fg: #0f172a;       /* slate-900 */
    --fg-muted: #475569; /* slate-600 */
  }
  .tone-light .card {
    @apply border-slate-200 bg-white text-slate-700;
    box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 16px 36px -20px rgb(15 23 42 / 0.22);
  }
  .tone-light .card-hover:hover {
    @apply border-brand-500/40 bg-white;
  }
  .tone-light .glass {
    @apply border-slate-200 bg-white/70;
  }
  .tone-light .section-label {
    @apply text-slate-500;
  }
  .tone-light .btn-secondary {
    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
  }
  .tone-light .btn-ghost {
    @apply text-slate-600 hover:bg-slate-900/[0.06] hover:text-slate-900;
  }

  /* Reusable hero aura — the dual-radial violet/blue glow that ~10 sub-page
     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
  .hero-aura {
    background-image:
      radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.20), transparent 70%),
      radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.14), transparent 70%);
  }

  /* Soft violet lift on hover for interactive cards (was inline arbitrary shadow). */
  .lift {
    @apply transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30;
    &:hover { box-shadow: 0 18px 40px -20px rgb(111 71 245 / 0.45); }
  }

  /* Consistent max-width content rail. */
  .rail {
    @apply mx-auto max-w-6xl px-5 sm:px-6;
  }

  /* Top-nav dropdown trigger button. */
  .nav-trigger {
    @apply inline-flex cursor-pointer items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:text-white;
  }
  .nav-trigger.is-open {
    @apply text-white;
  }

  /* Animated gradient underline that wipes in on hover (rocket-style nav). Sits
     inside the px-3 padding so it tracks the label width. */
  .nav-underline {
    position: relative;
  }
  .nav-underline::after {
    content: "";
    position: absolute;
    left: 12px;
    right: 12px;
    bottom: 5px;
    height: 1.5px;
    border-radius: 2px;
    background: linear-gradient(90deg, var(--color-accent-blue), var(--color-brand-400));
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  }
  .nav-underline:hover::after,
  .nav-underline:focus-visible::after,
  .nav-underline.is-open::after {
    transform: scaleX(1);
  }
  @media (prefers-reduced-motion: reduce) {
    .nav-underline::after { transition: none; }
  }
}

